document.addEventListener('DOMContentLoaded', () => {
    const messageForm = document.getElementById('messageForm');
    const messageInput = document.getElementById('messageInput');
    const messagesContainer = document.getElementById('messagesContainer');

    // 顯示留言列表
    async function loadMessages() {
        try {
            const response = await fetch('api/messages');
            const messages = await response.json();
            displayMessages(messages);
        } catch (error) {
            console.error('載入留言失敗:', error);
        }
    }

    // 顯示留言
    function displayMessages(messages) {
        messagesContainer.innerHTML = '';

        if (messages.length === 0) {
            messagesContainer.innerHTML = '<p>目前沒有留言。</p>';
            return;
        }

        // 按時間排序（最新的在前）
        messages.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

        messages.forEach(msg => {
            const messageElement = document.createElement('div');
            messageElement.className = 'message';
            messageElement.innerHTML = `
                <p>${msg.content}</p>
                <div class="message-info">
                    <span>時間: ${new Date(msg.timestamp).toLocaleString('zh-TW')}</span>
                    <span>按讚: ${msg.likes}</span>
                    <button class="like-btn" data-id="${msg.id}">按讚</button>
                    <button class="delete-btn" data-id="${msg.id}">刪除</button>
                </div>
            `;
            messagesContainer.appendChild(messageElement);
        });

        // 綁定按讚和刪除按鈕事件
        document.querySelectorAll('.like-btn').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                const id = e.target.dataset.id;
                await likeMessage(id);
            });
        });

        document.querySelectorAll('.delete-btn').forEach(btn => {
            btn.addEventListener('click', async (e) => {
                const id = e.target.dataset.id;
                await deleteMessage(id);
            });
        });
    }

    // 發表留言
    messageForm.addEventListener('submit', async (e) => {
        e.preventDefault();

        if (!messageInput.value.trim()) return;

        try {
            const content = messageInput.value.trim();
            await fetch('api/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content })
            });

            messageInput.value = '';
            await loadMessages(); // 重新載入留言
        } catch (error) {
            console.error('發表留言失敗:', error);
        }
    });

    // 按讚
    async function likeMessage(id) {
        try {
            await fetch(`api/messages/${id}/like`, { method: 'PUT' });
            await loadMessages(); // 重新載入留言
        } catch (error) {
            console.error('按讚失敗:', error);
        }
    }

    // 刪除留言
    async function deleteMessage(id) {
        try {
            if (!confirm('確定要刪除這則留言嗎？')) return;

            await fetch(`api/messages/${id}`, { method: 'DELETE' });
            await loadMessages(); // 重新載入留言
        } catch (error) {
            console.error('刪除留言失敗:', error);
        }
    }

    // 初始化載入留言
    loadMessages();
});

